class M:
    def __enter__(self):
        return 1
    def __exit__(self, t, val, tb):
        return 2
def main():
    m = M()
    with m:
        return 7
main()

class M:
    def __enter__(self):
        return 42
    def __exit__(self, t, val, tb):
        pass
def main():
    m = M()
    with m as x:
        return x
main()

def inner():
    yield 1
    yield 2
def outer():
    yield 0
    yield from inner()
    yield 3
def main():
    g = outer()
    return len(g)
main()

def outer():
    yield 10
    yield from range(3)
def main():
    g = outer()
    return len(g)
main()

class A:
    def f(self):
        return 7
class B(A):
    def b(self):
        return 1
class C(B):
    def g(self):
        return 1
c = C()
c.f()

class Animal:
    def __init__(self):
        self.x = 1
    def speak(self):
        return self.x
class Dog(Animal):
    def __init__(self):
        super().__init__()
    def speak(self):
        return 42
def make(kind):
    if kind == 1:
        return Animal()
    return Dog()
a = make(1)
b = make(2)
a.speak() + b.speak()

class Base:
    def __init__(self):
        self.n = 5
class Child(Base):
    def get(self):
        return self.n
c = Child()
c.get()

