class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def norm(self) -> int:
        return self.x * self.x + self.y * self.y

s = 0
for i in range(2000):
    p = Point(i, i % 7)
    s = s + p.norm()
print(s)

